mapper.select:
SELECT sdu.id AS flagId,sui.uid AS userId,sui.user_name,sui.real_name,sui.mobile, sdu.lead_state,sui.user_state,sd.name AS departmentName FROM sys_department_user sdu INNER JOIN sys_user_info sui ON sdu.user_id=sui.uid INNER JOIN sys_department sd ON sd.id=sdu.department_id WHERE sui.delete_state=1
AND sdu.department_id IN
#{departmentId}
AND sui.user_state=#{params.state}
AND sui.${params.searchType} LIKE concat('%',#{params.searchKeyword},'%')
ORDER BY sui.update_time DESC
